\n                                        ' [center][b][size=6]PERSONAL RELEASE[/size][/b][/center] \\n'\n                                        '[center][b]PLEASE SEED TORRENTLAND FAMILY[/b][/center]\\n'\n                                        '[center][url=https://codeberg.org/CvT/Uploadrr][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]',\n                        'signature': '[center][img=400]https://i.ibb.co/pBZZJjQS/Peticin-de-Animacin-de-Banner-ezgif-com-gif-to-webp-converter.webp[/img][/center]'},\n              'TTR': {'announce_url': 'https://torrenteros.org/announce/YOUR_PASSKEY',\n                      'anon': False,\n                      'anon_pr_signature': '\\n'\n                                           '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                      'anon_signature': '\\n[center][size=6]we are anonymous[/size][/center]',\n                      'api_key': 'API_KEY',\n                      'pr_signature': '\\n'\n                                      ' [center][b][size=6]PERSONAL RELEASE[/size][/b][/center] \\n'\n                                      '[center][b]PLEASE SEED TorrentEros[/b][/center]\\n'\n                                      '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]',\n                      'signature': '\\n'\n                                   '[center][b]PLEASE SEED TorrentEros[/b][/center]\\n'\n                                   '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]'},\n              'ULCX': {'announce_url': 'https://upload.cx/announce/YOUR_PASSKEY',\n                       'anon': False,\n                       'anon_pr_signature': '\\n'\n                                            '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                       'anon_signature': '\\n'\n                                         '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                       'api_key': 'API_KEY',\n                       'pr_signature': '\\n'\n                                       ' [center][b][size=6]PERSONAL RELEASE[/size][/b][/center] \\n'\n                                       '[center][b]PLEASE SEED ULCX FAMILY[/b][/center]\\n'\n                                       '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]',\n                       'signature': '\\n'\n                                    '[center][b]PLEASE SEED ULCX FAMILY[/b][/center]\\n'\n                                    '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]'},\n              'UTP': {'announce_url': 'https://utp.to/announce/YOUR_PASSKEY',\n                      'anon': False,\n                      'anon_pr_signature': '\\n'\n                                           '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                      'anon_signature': '\\n'\n                                        '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                      'api_key': 'API_KEY',\n                      'pr_signature': '\\n'\n                                      ' [center][b][size=6]PERSONAL RELEASE[/size][/b][/center] \\n'\n                                      '[center][b]PLEASE SEED UTP FAMILY[/b][/center]\\n'\n                                      '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]',\n                      'signature': '\\n'\n                                   '[center][b]PLEASE SEED UTP FAMILY[/b][/center]\\n'\n                                   '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]'},\n              'YU': {'announce_url': 'https://yu-scene.net/announce/YOUR_PASSKEY',\n                     'anon': False,\n                     'anon_pr_signature': '\\n'\n                                          '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                     'anon_signature': '\\n'\n                                       '[center][url=https://codeberg.org/RawSmoke/Singularity][img=40]https://i.ibb.co/jP8Qqjvm/Peticin-de-Animacin-de-Banner-ezgif-com-resize.gif[/img][/url][/center]',\n                     'api_key': 'API_KEY',\n                     'pr_signature': '\\n'\n                                     ' [center][b][size=6]PERSONAL RELEASE[/size][/b][/center] \\n'\n                                     '[center][b]PLEASE SEED YU-SCENE FAMILY[/b][/center]\\n'\n                                     '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]',\n                     'signature': '\\n'\n                                  '[center][b]PLEASE SEED YU-SCENE FAMILY[/b][/center]\\n'\n                                  '[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]'}},\n # Este es el bloque que lee la Aduana (RawLoadrr/rawncher.py:113), NO el\n # 'qbit' de dentro de TORRENT_CLIENTS. Dos detalles que importan:\n #\n #  1. 'qbit_user' TIENE que ser el literal 'YOUR_USERNAME'. El asistente\n #     decide si preguntarte la config comparando contra esa cadena exacta.\n #     Con cualquier otro valor el asistente no se lanza en una instalación\n #     nueva, y el handshake falla contra credenciales de plantilla.\n #\n #  2. 'qbit_url' va SIN puerto, porque el puerto se pasa aparte en\n #     'qbit_port'. Si lo pones en los dos sitios el log escribe\n #     http://127.0.0.1:8888:8888, que asusta pero es SOLO cosmético:\n #     qbittorrent-api usa el puerto de la URL e ignora el parámetro\n #     redundante, y conecta igual (así lleva años corriendo en producción).\n #     Se deja sin puerto por coherencia con el asistente, que pregunta la\n #     URL y el puerto por separado. Si ves ese doble puerto en un error de\n #     conexión, NO es la causa: mira las credenciales.\n 'qbit': {'enable_search': True,\n          'qbit_pass': 'PASSWORD',\n          'qbit_port': '8888',\n          'qbit_url': 'http://127.0.0.1',\n          'qbit_user': 'YOUR_USERNAME',\n          'torrent_storage_dir': '/app/RawLoadrr/qbit_backup'},\n 'version': '1.0.7'}\n",
    'mass_config.py': '# ==========================================\n# ⚙️ UNIT3D MASS EDITION SUITE - CONFIG\n# ==========================================\n# Namespace propio en el .env: prefijo ME_\n# Uso standalone: edita los fallbacks de os.getenv() directamente.\n# Uso via singularity/Docker: los ME_* del .env tienen prioridad.\n\nimport os\nfrom pathlib import Path\n\n# ─── 0. Autocuración del .env ────────────────────────────────────────────────\n# Un .env existente NO se regenera al reconstruir la imagen: es un fichero del\n# host montado dentro. Así que quien viene de una versión anterior se queda sin\n# las claves nuevas y hereda los valores por defecto del código sin enterarse —\n# y peor, sin poder cambiarlos desde el .env porque ni siquiera aparecen.\n#\n# ENV_DEFAULTS es la lista de claves que este módulo espera. ensure_env_keys()\n# añade SÓLO las que falten, nunca toca un valor ya escrito, y no hace nada si\n# están todas: es idempotente, se puede llamar en cada arranque.\nENV_DEFAULTS = [\n    ("ME_DEAD_HOSTS",        "imgbox.com,pixhost.to", "Hosts de imágenes caídos que disparan la regeneración"),\n    ("ME_REGEN_IMG_HOST",    "",                      "Destino de las capturas. Vacío = primer img_host_N vivo de RawLoadrr"),\n    ("ME_REGEN_SCREENS",     "",                      "Nº de capturas. Vacío = tantas como imágenes haya que reponer"),\n    ("ME_REGEN_KEEP_PNG",    "0",                     "1 conserva los PNG en tmp; 0 los borra tras subirlos"),\n    ("ME_REGEN_DRY_RUN",     "0",                     "1 = simulacro. Los flags --real/--dry-run mandan sobre esto"),\n    ("ME_REGEN_IMG_SIZE",    "350",                   "Ancho del [img=N] si la etiqueta original no traía uno"),\n    ("ME_REGEN_STATE_DIR",   "",                      "Dónde viven mapeo_qbit_*.json y completados_regen_*.txt. Vacío = directorio actual"),\n    ("ME_REGEN_ALL",         "0",                     "1 = procesa todo el cliente e ignora ID_START/ID_END"),\n    ("ME_REGEN_LIMIT",       "0",                     "Tope de torrents por tirada. 0 = sin tope"),\n    ("ME_REGEN_MAX_FALLOS",  "15",                    "Fallos seguidos tras los que se aborta la tirada"),\n]\n\n\ndef _localizar_env():\n    """Mismo orden de búsqueda que el cargador de abajo."""\n    aqui = Path(__file__).resolve().parent\n    for ruta in (aqui / ".env", aqui / "../../.env", Path("/app/.env")):\n        if ruta.exists():\n            return ruta.resolve()\n    return (aqui / "../../.env").resolve()\n\n\ndef ensure_env_keys(env_path=None, verbose=True):\n    """Añade al .env las claves que falten. Devuelve la lista de añadidas.\n\n    - No modifica ningún valor existente (ni siquiera si está vacío).\n    - Idempotente: la segunda llamada no añade nada.\n    - Escribe in situ (r+ y truncate), nunca os.replace: el .env suele ser un\n      bind-mount de fichero único y sustituirlo rompe el inodo del contenedor.\n    - Si el fichero no existe, lo crea.\n    """\n    ruta = Path(env_path) if env_path else _localizar_env()\n    try:\n        texto = ruta.read_text(encoding="utf-8") if ruta.exists() else ""\n    except OSError:\n        return []\n\n    presentes = set()\n    for linea in texto.splitlines():\n        limpia = linea.strip()\n        if not limpia or limpia.startswith("#") or "=" not in limpia:\n            continue\n        presentes.add(limpia.split("=", 1)[0].strip())\n\n    faltan = [(k, v, c) for k, v, c in ENV_DEFAULTS if k not in presentes]\n    if not faltan:\n        return []\n\n    nuevo = texto\n    if nuevo and not nuevo.endswith("\\n"):\n        nuevo += "\\n"\n    nuevo += "\\n# --- Mass Edition · regeneración de imágenes (añadido automáticamente) ---\\n"\n    for k, v, c in faltan:\n        nuevo += f"# {c}\\n{k}={v}\\n"\n\n    try:\n        ruta.parent.mkdir(parents=True, exist_ok=True)\n        with open(ruta, "r+" if ruta.exists() else "w", encoding="utf-8") as f:\n            f.write(nuevo)\n            f.truncate()\n    except OSError as e:\n        if verbose:\n            print(f"⚠️  No se pudo completar {ruta}: {e}")\n        return []\n\n    if verbose:\n        print(f"🔧 {ruta.name} completado con {len(faltan)} clave(s) nueva(s): "\n              + ", ".join(k for k, _v, _c in faltan))\n    return [k for k, _v, _c in faltan]\n\n\ntry:\n    from dotenv import load_dotenv\n    _here = Path(__file__).resolve().parent\n    # Claves que se pasan por ejecución (el TUI las exporta al lanzar el\n    # subproceso, y el README documenta `export ID_START=…` para uso suelto).\n    # Éstas mandan sobre el fichero; el resto, no. Ver el comentario de abajo.\n    _RUNTIME_KEYS = ("ID_START", "ID_END", "ID_FILENAME", "EDIT_MODE",\n                     "ME_REGEN_ALL", "ME_REGEN_DRY_RUN", "ME_REGEN_KEEP_PNG",\n                     "ME_REGEN_SCREENS", "ME_REGEN_IMG_HOST", "ME_DEAD_HOSTS",\n                     "ME_REGEN_LIMIT", "ME_REGEN_MAX_FALLOS")\n    _runtime = {k: os.environ[k] for k in _RUNTIME_KEYS if k in os.environ}\n\n    for _ep in [_here / ".env", _here / "../../.env", Path("/app/.env")]:\n        if _ep.exists():\n            # override=True es obligatorio: el compose usa `env_file: ./config/.env`,\n            # así que los valores del .env quedan CONGELADOS en el entorno del\n            # contenedor cuando arranca. Sin override, load_dotenv respeta ese\n            # entorno viejo y cualquier cambio hecho desde el TUI (_write_env_key)\n            # es invisible para los procesos nuevos: el módulo seguiría apuntando\n            # al tracker anterior con la cookie y la API key anteriores.\n            load_dotenv(_ep, override=True)\n            break\n\n    # Completar el .env con las claves nuevas y recargar, para que un fichero\n    # heredado de una versión anterior no deje al usuario sin poder configurarlas.\n    try:\n        if ensure_env_keys(_ep if \'_ep\' in dir() else None):\n            load_dotenv(_ep, override=True)\n    except Exception:\n        pass\n\n    # …pero lo que venga explícito en esta ejecución vuelve a ganar.\n    os.environ.update(_runtime)\nexcept ImportError:\n    pass\n\n# ─── 0b. Lectura estricta de banderas ────────────────────────────────────────\n# "cualquier cosa que no sea 0 es verdadero" es una trampa: un valor como "n",\n# "no" o "false" se leía como VERDADERO y dejaba la herramienta encerrada en\n# simulacro pasara lo que pasara. Aquí sólo valen tokens reconocidos, y lo que\n# no se reconozca avisa y se toma como falso en vez de decidir en silencio.\n_CIERTO = {"1", "true", "yes", "y", "on", "si", "sí", "s", "t"}\n_FALSO  = {"0", "false", "no", "n", "off", "", "none", "null", "f"}\n\n\ndef flag(nombre, por_defecto="0"):\n    crudo = os.getenv(nombre, por_defecto)\n    v = str(crudo).strip().strip("\'\\"").lower()\n    if v in _CIERTO:\n        return True\n    if v in _FALSO:\n        return False\n    print(f"⚠️  {nombre}={crudo!r} no se entiende; lo trato como desactivado. "\n          f"Usa 1/0.")\n    return False\n\n\n# ─── 1. Credenciales y Tracker (namespace ME_) ────────────────────────────────\nBASE_URL          = os.getenv("ME_TRACKER_URL",         "https://tu-tracker-unit3d.com")\nUSERNAME          = os.getenv("ME_TRACKER_USERNAME",    "TuUsuario")\nCOOKIE_NAME       = os.getenv("ME_TRACKER_COOKIE_NAME", "tu_tracker_session")\nCOOKIE_VALUE      = os.getenv("ME_TRACKER_COOKIE",      "")\nTRACKER_API_KEY   = os.getenv("ME_TRACKER_API_KEY",     "")\nCUSTOM_USER_AGENT = os.getenv("ME_CUSTOM_USER_AGENT",   "undici")\nTRACKER_ABBREV    = os.getenv("ME_TRACKER_DEFAULT",     "TRACKER")\n\n# ─── 2. APIs de imágenes (namespace ME_) ──────────────────────────────────────\nIMGBB_API      = os.getenv("ME_IMGBB_API",     "")\nPTSCREENS_API  = os.getenv("ME_PTSCREENS_API", "")\n\n# ─── 3. Rutas (namespace ME_) ─────────────────────────────────────────────────\nTMP_DIR_PATH = os.getenv("ME_TMP_ROOT", "/app/RawLoadrr/tmp")\n\n# ─── 4. Rango de IDs (vars ME-only, sin riesgo de colisión) ──────────────────\nID_INICIO = int(os.getenv("ID_START", "14"))\nID_FIN    = int(os.getenv("ID_END",   "2000"))\nID_FILE   = os.getenv("ID_FILENAME",  "ids.txt")\n\n# ─── 5. Modo de edición y textos (vars ME-only) ───────────────────────────────\nEDIT_MODE        = os.getenv("EDIT_MODE",        "BANNER_URL")\nBANNER_URL_NUEVA = os.getenv("BANNER_URL_NUEVA", "")\nBANNER_IMG_NUEVA = os.getenv("BANNER_IMG_NUEVA", "")\nFIRMA_TEXT_NUEVA = os.getenv("FIRMA_TEXT_NUEVA", "")\nFIRMA_FULL_NUEVA = os.getenv("FIRMA_FULL_NUEVA", "")\nFIND_URL         = os.getenv("FIND_URL",         "")\nREPLACE_URL      = os.getenv("REPLACE_URL",      "")\nBLOCK_VIEJO      = os.getenv("BLOCK_VIEJO",      "")\nBLOCK_NUEVO      = os.getenv("BLOCK_NUEVO",      "")\n\n# ─── 6. Textos estáticos ──────────────────────────────────────────────────────\nMSG_VIEJO = "[center][b]PLEASE SEED MILNUEVE FAMILY[/b][/center]"\nMSG_NUEVO = "[center][b]🌱 ¡La magia del P2P eres tú! Por favor, quédate compartiendo (seeding) para mantener viva la comunidad. 🌱[/b][/center]"\n\nBANNER_VIEJO = "[center][url=https://codeberg.org/CvT/Uploadrr][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]"\nBANNER_NUEVO = "[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/0RrzLmSr/RAW-bruma-servers.png[/img][/url][/center]"\n\nFIRMAS_VIEJAS = [\n    "[center][b]PLEASE SEED MILNUEVE FAMILY[/b][/center]",\n    "[center][url=https://codeberg.org/CvT/Uploadrr][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]",\n]\n\n# ─── 7. Settings del bot ──────────────────────────────────────────────────────\nDELAY_MIN = float(os.getenv("ME_DELAY_MIN", "4.5"))\nDELAY_MAX = float(os.getenv("ME_DELAY_MAX", "7.5"))\n\n# ─── 7b. Regeneración de imágenes (05_image_regenerator) ─────────────────────\n# Hosts de imágenes muertos: si la descripción del tracker apunta a alguno de\n# ellos, el torrent entra en la cola de regeneración. Lista separada por comas.\nDEAD_HOSTS = [\n    h.strip().lower()\n    for h in os.getenv("ME_DEAD_HOSTS", "imgbox.com,pixhost.to").split(",")\n    if h.strip()\n]\n\n# Host de destino para las capturas nuevas. Vacío = usa el primer img_host_N de\n# RawLoadrr que no esté en DEAD_HOSTS. No introduce credenciales nuevas: las\n# API keys siguen viniendo de RawLoadrr/data/config.py.\nREGEN_IMG_HOST = os.getenv("ME_REGEN_IMG_HOST", "").strip().lower()\n\n# Nº de capturas por torrent. Vacío = usa DEFAULT.screens de RawLoadrr.\nREGEN_SCREENS = os.getenv("ME_REGEN_SCREENS", "").strip()\n\n# 1 = conserva los PNG en tmp/. 0 = los borra tras subirlos con éxito y deja\n# solo MediaInfo.json + meta.json + DESCRIPTION.txt (unos cientos de KB por\n# torrent en vez de ~13 MB).\nREGEN_KEEP_PNG = flag("ME_REGEN_KEEP_PNG", "0")\n\n# 1 = no escribe nada en el tracker; imprime el diff de la descripción.\nREGEN_DRY_RUN = flag("ME_REGEN_DRY_RUN", "0")\n\n# Ancho del [img=N] en el BBCode nuevo (mismo formato que COMMON.py).\nREGEN_IMG_SIZE = os.getenv("ME_REGEN_IMG_SIZE", "350").strip()\n\n# Directorio donde viven los ficheros de estado (mapeo_qbit.json,\n# completados_regen.txt). Por defecto el cwd, igual que 01-04.\nREGEN_STATE_DIR = os.getenv("ME_REGEN_STATE_DIR", "").strip() or "."\n\n# 1 = procesa TODO lo que haya en el cliente para este tracker e ignora\n# ID_START/ID_END. El mapa del cliente ya es la lista real de torrents del\n# usuario, así que los rangos sólo estorban.\nREGEN_ALL = flag("ME_REGEN_ALL", "0")\n\n# Tope de torrents por tirada (0 = sin tope). Sirve para hacer la primera\n# pasada en lotes pequeños y revisar el resultado antes de soltar las 3000.\nREGEN_LIMIT = int(os.getenv("ME_REGEN_LIMIT", "0") or 0)\n\n\n# ─── 8. Utilidades ────────────────────────────────────────────────────────────\ndef filter_ids_by_range(ids):\n    """Filtra una lista de IDs (strings) por el rango ID_START/ID_END.\n\n    get_target_ids() depende de ids.txt (lo genera 01_scraper). 05 construye su\n    propia lista desde el cliente torrent, así que necesita el filtro suelto.\n    """\n    out = []\n    for tid in ids:\n        try:\n            if ID_INICIO <= int(tid) <= ID_FIN:\n                out.append(str(tid))\n        except (TypeError, ValueError):\n            continue\n    return sorted(out, key=int)\n\n\ndef get_target_ids():\n    """Retorna la lista final de IDs a procesar (de ids.txt filtrada por rango)."""\n    ids = []\n    if os.path.exists(ID_FILE):\n        with open(ID_FILE, "r") as f:\n            for line in f:\n                stripped = line.strip()\n                if not stripped:\n                    continue\n                try:\n                    int(stripped)\n                    ids.append(stripped)\n                except ValueError:\n                    pass\n    if ids:\n        return [tid for tid in ids if ID_INICIO <= int(tid) <= ID_FIN]\n    return [str(i) for i in range(ID_INICIO, ID_FIN + 1)]\n',
}
