echo "2) EDITA ./config/.env     (lo lee la aplicación)"
echo "     La cookie del tracker, las API keys, el namespace ME_*."
echo "     CUSTOM_USER_AGENT y ME_CUSTOM_USER_AGENT deben COINCIDIR:"
echo "     si no, el scraper se come un 403 en la primera petición."
echo ""
echo "   Los otros tres (config.py, singularity_config.py, mass_config.py) ya"
echo "   están creados desde plantilla y leen del .env: normalmente no se tocan."
echo ""
echo "3) ARRANCA:"
echo "     make build     # la primera vez; en hardware modesto tarda"
echo "     make up"
